const rx = /((\d{4}-[01]\d-[0-3]\d)(T[0-2]\d:[0-5]\d:[0-5]\d))(\.\d+)?([+-][0-2]\d:[0-5]\d|Z)/;
const dayMs = 1000 * 60 * 60 * 24;
function parseDate(input) {
  // Transform date from text to date
  return new Date(rx.exec(input)[1]);
}
function getNextPeriodStartDate(startDate, plannedStartDate) {
  return getNextStartDate(startDate, plannedStartDate);
}
function getLastPeriodStartDate(startDate, plannedStartDate) {
  return getNextStartDate(startDate, plannedStartDate, args.Parameters.NumberOfFuturePeriods);
}
function getNextStartDate(startDate, plannedStartDate, numberOfFuturePeriods = 1) {
  const result = new Date(plannedStartDate);
  switch (args.Parameters.Duration) {
    case 'Days':
      const daysShift = result.getDate() + args.Parameters.NumberOfDurationsInPeriod * numberOfFuturePeriods;
      result.setDate(daysShift);
      return result;
    case 'Weeks':
      const weeksShift = result.getDate() + args.Parameters.NumberOfDurationsInPeriod * numberOfFuturePeriods * 7;
      result.setDate(weeksShift);
      return result;
    case 'Months':
      const monthsShift = result.getMonth() + args.Parameters.NumberOfDurationsInPeriod * numberOfFuturePeriods;
      result.setMonth(monthsShift);
      const month = monthsShift % 12;
      if (result.getMonth() === month) {
        while (result.getDate() < startDate.getDate()) {
          result.setDate(result.getDate() + 1);
        }
      }
      while (result.getMonth() > month) {
        result.setDate(result.getDate() - 1);
      }
      return result;
    default:
      throw new Error('Unknown Duration Parameter!');
  }
}
function validatePeriod(period, startDate) {
  let duration = undefined;
  let durationsTotal = undefined;
  switch (args.Parameters.Duration) {
    case 'Days':
      duration = (period.PlannedEndDate.getTime() - period.PlannedStartDate.getTime() + 1000) / dayMs;
      durationsTotal = (period.PlannedStartDate.valueOf() - startDate.valueOf()) / dayMs;
      break;
    case 'Weeks':
      duration = (period.PlannedEndDate.getTime() - period.PlannedStartDate.getTime() + 1000) / (dayMs * 7);
      durationsTotal = (period.PlannedStartDate.valueOf() - startDate.valueOf()) / (dayMs * 7);
      break;
    case 'Months':
      const nextStartDate = new Date(period.PlannedEndDate.valueOf() + 1000);
      duration =
        (nextStartDate.getFullYear() - period.PlannedStartDate.getFullYear()) * 12 +
        (nextStartDate.getMonth() - period.PlannedStartDate.getMonth());
      durationsTotal =
        (period.PlannedStartDate.getFullYear() - startDate.getFullYear()) * 12 +
        (period.PlannedStartDate.getMonth() - startDate.getMonth());
      break;
    default:
      throw new Error('Unknown Duration Parameter!');
  }
  if (duration !== args.Parameters.NumberOfDurationsInPeriod) {
    throw new Error(`Period #${period.Id} ${period.PlannedStartDate.toISOString().slice(0, 10)} - ${period.PlannedEndDate.toISOString().slice(
      0, 10)} duration is not equal ${args.Parameters.NumberOfDurationsInPeriod} ${args.Parameters.Duration}!`
    );
  }
  if (durationsTotal % args.Parameters.NumberOfDurationsInPeriod !== 0) {
    throw new Error(`Period #${period.Id} PlannedStartDate ${period.PlannedStartDate.toISOString().slice(0, 10)} is invalid for ${
      args.Parameters.Duration} period!`);
  }
}

