  where: `PlannedEndDate>DateTime.Parse("${startDate.toISOString().slice(0, 10)}T00:00:00")`,
  orderBy: 'PlannedStartDate desc',
  take: 1
});
let prevPeriod = lastPeriod.length
  ? {
    Id: lastPeriod[0].id,
    PlannedStartDate: parseDate(lastPeriod[0].plannedStartDate),
    PlannedEndDate: parseDate(lastPeriod[0].plannedEndDate)
  }
  : undefined;
if (prevPeriod) {
  validatePeriod(prevPeriod, startDate);
}
let nextPeriodStartDate = prevPeriod
  ? getNextPeriodStartDate(startDate, prevPeriod.PlannedStartDate)
  : new Date(startDate);
const today = new Date(new Date().toISOString().slice(0, 10));
const partitionKey = `${args.Parameters.Duration} ${startDate.toISOString().slice(0, 10)}`;
const lastStartDate = getLastPeriodStartDate(startDate, startDate.valueOf() < today.valueOf() ? today : startDate);
const commands = [];
//name logic
let nameFunc;
let index = 0;
const choise = args.Parameters.NameBase.toLowerCase();
if (choise === "date") {
  nameFunc = (arr) => {
    return `${arr[0]} - ${arr[1]}`
  }
}
else if (["pi", "ti"].includes(choise)) {
  nameFunc = (arr) => {
    return `${choise.toUpperCase()}${arr[2]}`
  }
  index = await api.queryAsync("Period", {
    where: `PlannedStartDate < DateTime.Parse("${nextPeriodStartDate.toISOString().slice(0, 10)}")`,
