  const nextPeriodEndDate = new Date(nextStartDate.valueOf() - 1000);
  index++;
  commands.push({
    command: 'ActivateNamedTrigger',
    payload: {
      name: 'Generate Period',
      data: {
        Prev: prevPeriod,
        Name: nameFunc([nextPeriodStartDate.toISOString().slice(0, 10), nextPeriodEndDate.toISOString().slice(0, 10), index]),
        PlannedStartDate: nextPeriodStartDate,
        PlannedEndDate: nextPeriodEndDate
      },
      partitionKey: partitionKey
    }
  });
  prevPeriod = {
    Id: 0,
    PlannedStartDate: nextPeriodStartDate,
    PlannedEndDate: nextPeriodEndDate
  };
  nextPeriodStartDate = nextStartDate;
  if (commands.length === 1000) {
    break;
  }
}
// @ts-ignore
return commands;

