const api = require('targetprocess/api/v2');

const utils = require('utils');
const periodType = args.Parameters.PeriodType;
const currentParent = args.Parameters.ParentTypes.find(x => args.Current[x]);
const previousParent = args.Previous ? args.Parameters.ParentTypes.find(x => args.Previous[x]) : undefined;
if (currentParent || previousParent) {
  const [availabilities, current] = await Promise.all([
    api.queryAsync('Availability', {
      where: `${periodType}.Id=${args.Current[periodType].Id} and ${currentParent || previousParent}.Id=${
        currentParent ? args.Current[currentParent].Id : args.Previous[previousParent].Id
      }`,
      select: `{Id,Parent:${currentParent || previousParent},Period:${periodType}}`
    }),
    api.queryAsync('AvailabilityDemand', {
      where: `Demand.Id=${args.ResourceId}`,
      select: `{Id,Parent:Availability.${currentParent || previousParent},Period:Availability.${periodType}}`
    })
  ]);
  if (availabilities.length < 1) {
    console.log('There is no matched Availability'); // @ts-ignore
    return current.map(x => {
      return utils.deleteResource('AvailabilityDemand', x.id);
    });
  } else {
    const availability = availabilities[0];
    if (currentParent) {
      const obsolete = [];
      let isConnected = false;
      for (const availabilityDemand of current) {
        if (!availabilityDemand.parent || availabilityDemand.parent.id !== availability.parent.id || availabilityDemand.parent.resourceType !== availability.parent.resourceType
          || !availabilityDemand.period || availabilityDemand.period.id !== availability.period.id) {
          obsolete.push(availabilityDemand.id);
        } else {
          if (isConnected) {
            obsolete.push(availabilityDemand.id);
          } else {
            isConnected = true;
          }
        }
      }
      const fields = {Availability: {Id: availability.id}, Demand: {Id: args.ResourceId}}; // @ts-ignore
      return (!isConnected
        ? obsolete.length
          ? [utils.updateResource('AvailabilityDemand', obsolete.shift(), fields)]
          : [utils.createResource('AvailabilityDemand', fields)]
        : []
      ).concat(obsolete.map(id => {
        return utils.deleteResource('AvailabilityDemand', id);
      }));
    } else {
      console.log('There is no matched Parent'); // @ts-ignore
      return current.map(x => {
        return utils.deleteResource('AvailabilityDemand', x.id);
      });
    }
  }
}

