async function main(params, iType, iParentType, nameStart, excludedItems = []) {
  const iPeriodType = "Period";
  const pastPeriodsAmount = params.PastPeriodsAmount ? params.PastPeriodsAmount : 1000;
  const useParentProject = ['AgileReleaseTrain', 'SolutionTrain'].includes(iParentType);
  const periodInfoSelector = `{id, name, start:PlannedStartDate, end: PlannedEndDate, iParents: ${iType}s.select(${iParentType}.Id)}`;
  const [unfinishedPeriods, parents, [firstIterPeriod]] = await Promise.all([
    api.queryAsync(iPeriodType, {
      where: `PlannedEndDate >= Today`,
      select: periodInfoSelector,
      orderBy: `PlannedEndDate`
    }),
      api.queryAsync(iParentType, {
        where: `id == ${args.ResourceId}`,
        select: `{id${useParentProject ? ', project: project.id' : ''}}`
      }),
    api.queryAsync(iPeriodType, {
      where: `${iType}s.count>0`,
      select: "{start: PlannedStartDate}",
      orderBy: `PlannedStartDate`,
      take: 1
    }),
  ]);
  const allPeriods = unfinishedPeriods;
  if (allPeriods.length === 0) {
    throw new Error(`There are no ${iPeriodType}s`);
  }
  let startIndex = 0;
  if (firstIterPeriod) {
    const firstIterPeriodStart = parseDate(firstIterPeriod.start);
    const firstPeriodStart = parseDate(allPeriods[0].start);
    if (new Date(firstIterPeriodStart).getTime() < new Date(firstPeriodStart).getTime()) {
      startIndex = await api.queryAsync(iPeriodType, {
        where: `PlannedEndDate > DateTime.Parse("${firstIterPeriodStart}") AND PlannedEndDate < DateTime.Parse("${firstPeriodStart}")`,
        result: 'Count'
      });
    }
  }
  const cmds = [];
  if (useParentProject) {
    allPeriods.forEach((period, i) => {
      const item = processPeriod(nameStart, period.start, period.end, startIndex, i, period.id, iPeriodType, iType);
      const items = [];
      parents.forEach(parent => {
        if (!period.iParents.includes(parent.id)) { items.push(Object.assign({}, item, { Project: { Id: parent.project }, [iParentType]: { Id: parent.id } })) }
      })
      if (items.length > 0) {
        cmds.push(utils.updateResource(iPeriodType, period.id, { [`${iType}s`]: { Items: items } }))
      }
    });
  } else {
    allPeriods.forEach((period, i) => {
      const item = processPeriod(nameStart, period.start, period.end, startIndex, i, period.id, iPeriodType, iType);
      const items = [];
      parents.forEach(parent => {
        if (!period.iParents.includes(parent.id)) { items.push(Object.assign({}, item, { [iParentType]: { Id: parent.id }})) }
      })
      if (items.length > 0) {
        cmds.push(utils.updateResource(iPeriodType, period.id, { [`${iType}s`]: { Items: items } }))
      }
    });
  }
  return cmds
}

