  const [nextStates] = await api.queryAsync("EntityState", {
    where: `Workflow.EntityType.Name="${args.ResourceType}" AND (IsInitial=true OR IsPlanned=true)`,
    select: `NextStates.OrderBy(NumericPriority).Select({Id,Name,NumericPriority,IsFinal})`,
    orderBy: 'NumericPriority desc',
    take: 1
  })

  const inProgress = nextStates.find(x => x.isFinal === false);
  const done = nextStates.find(x => x.isFinal === true);

  return utils.updateResource(args.ResourceType, args.ResourceId, {
    EntityState: { Id: isActive ? inProgress.id : done.id }
  })
}

