const api = context.getService("targetprocess/api/v2"), millisecondsPerDay = 1000 * 60 * 60 * 24, // Day in milliseconds
  rx = /(\d{4}-[01]\d-[0-3]\d)(T[0-2]\d:[0-5]\d:[0-5]\d)([+-][0-2]\d:[0-5]\d|Z)/

const cfIterationLength = "Iteration Length", cfIterationCount = "Iteration Count", teamIterations = []

const pi = await api.getByIdAsync(args.ResourceType, args.ResourceId, {
  select: `{Name,StartDate,TeamIds:TeamIterations.OrderBy(Team.Id).Select(Team.Id).Distinct(),IterationLength:AgileReleaseTrain.CustomValues.Number("${cfIterationLength}"),IterationCount:AgileReleaseTrain.CustomValues.Number("${cfIterationCount}"),Teams:AgileReleaseTrain.Teams.OrderBy(Id).Select({Id,Name})}`
});

if (!pi) {
  console.error(`args.ResourceType #${args.ResourceId} not found`)
  return
}

if (!pi.iterationCount || !pi.iterationLength) {
  console.log(`${cfIterationCount} ('${pi.iterationCount}') and ${cfIterationLength} ('${pi.iterationLength}') should be greater than 0`)
  return
}

if (!pi.teams || pi.teams.length === 0) {
  console.log(`No teams in Train #${args.Current.AgileReleaseTrain.Id}`)
  return
}

const piStartDate = parseDate(pi.startDate)

pi.teams.forEach(team => {
  if (pi.teamIds.indexOf(team.id) === -1) {
    for (var j = 0; j < pi.iterationCount; j++) {
      const startDate = new Date(piStartDate.valueOf() + millisecondsPerDay * j * pi.iterationLength)
      const endDate = new Date(startDate.valueOf() + millisecondsPerDay * pi.iterationLength - 1000)
      teamIterations.push({
        Name: `${pi.name} Iteration${j + 1}`, StartDate: startDate.toISOString().slice(0, -1), EndDate: endDate.toISOString().slice(0, -1), Team: { Id: team.id }
      })
    }
  }
})

const piEndDate = new Date(piStartDate.valueOf() + millisecondsPerDay * (pi.iterationCount * pi.iterationLength) - 1000)

return {
  command: 'targetprocess:UpdateResource',
  payload: {
    resourceType: args.ResourceType,
    resourceId: args.ResourceId,
    fields: {
      TeamIterations: { Items: teamIterations },
      EndDate: piEndDate.toISOString().slice(0, -1),
      ["Generate Iterations"]: false
    }
  }
}

function parseDate(input) {
  return new Date(rx.exec(input)[1]);
}

